select finType.FINPROD_ID as id, NVL(NVL(fin.FINPROD_ABBR,fin.FINPROD_NAME),finType.FINPROD_ID) as text, finType.TYPE_18 as object from FIN_PRODUCT_TYPE finType /** 标的类金融产品 **/ LEFT JOIN FIN_PRODUCT fin ON finType.FINPROD_ID = fin.FINPROD_ID where 1=1
and (finType.FINPROD_ID like concat('%',concat(#{search},'%')) or fin.FINPROD_ABBR like concat('%',concat(#{search},'%')) or fin.FINPROD_NAME like concat('%',concat(#{search},'%')))
and fin.FINPROD_ID = #{finprodId}
AND finType.TYPE_18 IN
#{item}
and finType.TYPE_18 = #{assetType}
and fin.FINPROD_ID = #{initValue}

select fin.FINPROD_ID as id, NVL(fin.FINPROD_ABBR,fin.FINPROD_NAME) as text, finType.TYPE_18 as object from FIN_PRODUCT fin /** 标的类金融产品 **/ LEFT JOIN FIN_PRODUCT_TYPE finType ON finType.FINPROD_ID = fin.FINPROD_ID where 1=1 AND finType.TYPE_18 IN ('01','13') /** 债券、其他债权类**/
and (fin.FINPROD_ID like concat('%',concat(#{search},'%')) or fin.FINPROD_ABBR like concat('%',concat(#{search},'%')) or fin.FINPROD_NAME like concat('%',concat(#{search},'%')))
and fin.FINPROD_ID = #{finprodId}
and finType.TYPE_18 = #{assetType}
and fin.FINPROD_ID = #{initValue}

select finType.FINPROD_ID as id, NVL(NVL(fin.FINPROD_ABBR,fin.FINPROD_NAME),finType.FINPROD_ID) as text, finType.TYPE_18 as object from FIN_PRODUCT_TYPE finType /** 标的类金融产品 **/ LEFT JOIN FIN_PRODUCT fin ON finType.FINPROD_ID = fin.FINPROD_ID where 1=1 AND ( finType.TYPE_18 IN ('01','13') /** 债券、其他债权类**/ OR (finType.TYPE_18 = '07' and finType.TYPE_1 IN ('01','03')) /** 存款类资产：存放同业、同业借款**/ OR (finType.TYPE_18 = '09' and finType.TYPE_1 IN ('02','04')) /** 回购类资产：质押式逆回购、买断式逆回购**/ )
and (finType.FINPROD_ID like concat('%',concat(#{search},'%')) or fin.FINPROD_ABBR like concat('%',concat(#{search},'%')) or fin.FINPROD_NAME like concat('%',concat(#{search},'%')))
and fin.FINPROD_ID = #{finprodId}
and finType.TYPE_18 = #{assetType}
and fin.FINPROD_ID = #{initValue}
